1	/**
2	 * Guards the contract between `linear:plan`, which stores an implementation plan in a
3	 * Linear issue's description, and `linear:run`, which executes a valid stored plan
4	 * verbatim or falls back to a run-local fresh plan when the artifact is unusable.
5	 *
6	 * Five properties are load-bearing, and each fails silently without a guard:
7	 *
8	 * 1. The stored-plan section names `linear:run` reads match the ones `linear:plan` writes.
9	 *    This is the real rot: the two files have no import between them, so renaming a
10	 *    section in the producer breaks the consumer with nothing failing in between.
11	 * 2. `linear:run` enumerates every validation verdict and maps it to an execution mode.
12	 *    A verdict quietly dropped can turn an unusable artifact into executable instructions.
13	 * 3. `linear:run` never dispatches `linear:plan` or rewrites the ticket. Its fresh-plan
14	 *    path must remain a run-local fallback rather than silently replacing the artifact.
15	 * 4. The two skills agree on the stored format version. `Format:` is the only thing that
16	 *    keeps "written under an older template" apart from "corrupt", and a version the
17	 *    producer writes but the consumer does not read collapses that distinction.
18	 * 5. Expert review is an enhancement, never a gate. The pipeline states no scoring
19	 *    threshold and no revision budget, and `linear:plan` stores unconditionally with
20	 *    no plan-mode transition — a re-introduced gate would silently start losing plans.
21	 * 6. Expert review is opt-in for `plan` alone. The pipeline names `plan` as the only
22	 *    caller that may skip the step and records an explicit skipped score; the
23	 *    `--experts-review` flag lives in `plan` and nowhere else, so no other caller can
24	 *    quietly grow the skip.
25	 *
26	 * The section names are extracted from the producer's own text rather than hardcoded,
27	 * so the guard tracks the source instead of a copy of it.
28	 *
29	 * What this CANNOT prove: that the gate runs, or that the model honours it. CI sees text
30	 * in a file, nothing more — the same limit `sharedRulesInvocation.test.ts` states for its
31	 * own presence checks. Worse here, no workflow executes this test at all (nothing under
32	 * `.github/workflows/` runs `bun test`), so it gates locally and in review, not in CI.
33	 * Runtime evidence comes from the dry-run recorded on the PR.
34	 */
35	import { readFile } from "node:fs/promises";
36	import { join } from "node:path";
37	
38	import { describe, expect, test } from "bun:test";
39	
40	const actionDir = join(import.meta.dirname, "..");
41	const repoRoot = join(actionDir, "..", "..", "..");
42	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
43	
44	const readSkill = (name: string): Promise<string> =>
45	  readFile(join(skillsDir, name, "SKILL.md"), "utf8");
46	
47	const [linearPlan, linearRun, plan, run, runPrimed, pipeline] = await Promise.all([
48	  readSkill("linear:plan"),
49	  readSkill("linear:run"),
50	  readSkill("plan"),
51	  readSkill("run"),
52	  readSkill("run-primed"),
53	  readFile(join(skillsDir, "plan/references/pipeline.md"), "utf8"),
54	]);
55	
56	/** Every verdict `linear:run`'s validation table must name, fallback ones first. */
57	const fallbackVerdicts = ["missing", "version-mismatch", "malformed", "unverifiable"];
58	const allVerdicts = [...fallbackVerdicts, "valid"];
59	
60	/**
61	 * `### <name>` rows of the stored-plan template in `linear:plan`, split by its own
62	 * required/caller-owned marker. Reading the producer's template is what makes a renamed
63	 * section fail here rather than at runtime against a live ticket.
64	 */
65	function storedSections(source: string, kind: "required" | "caller-owned"): string[] {
66	  const rows = source.matchAll(/^###\s+(.+?)\s+<-\s+(required|caller-owned)$/gm);
67	  return [...rows].filter((row) => row[2] === kind).map((row) => row[1].trim());
68	}
69	
70	const requiredSections = storedSections(linearPlan, "required");
71	const callerOwnedSections = storedSections(linearPlan, "caller-owned");
72	
73	/** The `Source | Section` table rows in `linear:run`, keyed by the source cell. */
74	function sectionTableRow(source: string, key: string): string {
75	  const row = source
76	    .split("\n")
77	    .map((line) => line.split("|").map((cell) => cell.trim()))
78	    .find((cells) => cells.length > 2 && cells[1] === key);
79	  return row ? row[2] : "";
80	}
81	
82	describe("linear plan contract", () => {
83	  test("the stored-plan template still exposes a required/caller-owned split", () => {
84	    expect(requiredSections.length).toBeGreaterThan(1);
85	    expect(callerOwnedSections.length).toBeGreaterThan(0);
86	  });
87	
88	  test.each(allVerdicts)("linear:run names the %s verdict", (verdict) => {
89	    expect(linearRun).toContain(`**${verdict}**`);
90	  });
91	
92	  test.each(fallbackVerdicts)("the %s verdict selects a fresh plan", (verdict) => {
93	    const message = linearRun.split("\n").find((line) => line.startsWith(`- ${verdict} —`));
94	    expect(`${verdict}: ${message ?? "<no message line>"}`).toContain(
95	      "drafting a fresh implementation plan",
96	    );
97	  });
98	
99	  test("the verdict table maps valid to stored-plan and every other verdict to fresh-plan", () => {
100	    const validRow = linearRun
101	      .split("\n")
102	      .find((line) => line.includes("| **valid**") && line.includes("`stored-plan`"));
103	    const fallbackRow = linearRun
104	      .split("\n")
105	      .find(
106	        (line) =>
107	          line.includes("`fresh-plan`") &&
108	          fallbackVerdicts.every((verdict) => line.includes(`**${verdict}**`)),
109	      );
110	    expect(validRow).toContain("`stored-plan`");
111	    expect(fallbackRow).toContain("`fresh-plan`");
112	  });
113	
114	  test("linear:run never invokes the producer or overwrites the stored artifact", () => {
115	    expect(linearRun).not.toContain("Skill(autopilot:linear-plan)");
116	    expect(linearRun).toContain("never writes or repairs a stored plan");
117	    expect(linearRun).toContain("Do not store it on the Linear issue");
118	  });
119	
120	  test.each([
121	    ["admission", "Only the Linear issue is required"],
122	    ["snapshot", "The plan is a snapshot, not a live view"],
123	  ])("linear:run states the %s contract", (_label, needle) => {
124	    expect(linearRun).toContain(needle);
125	  });
126	
127	  test("linear:run uses the shared planning pipeline for its fresh-plan path", () => {
128	    expect(linearRun).toContain("[pipeline.md](../plan/references/pipeline.md)");
129	    expect(linearRun).toContain('task 4 ("Establish plan")');
130	    expect(linearRun).toContain('task 5 ("Validate plan")');
131	    expect(linearRun).toContain('task 6 ("Finalize plan")');
132	  });
133	
134	  test.each(requiredSections)("linear:run consumes `### %s` from the stored plan", (name) => {
135	    expect(sectionTableRow(linearRun, "Stored plan")).toContain(`\`### ${name}\``);
136	  });
137	
138	  test.each(callerOwnedSections)("`### %s` is stored but explicitly not consumed", (name) => {
139	    expect(sectionTableRow(linearRun, "Stored plan, **unused**")).toContain(`\`### ${name}\``);
140	    expect(sectionTableRow(linearRun, "Stored plan")).not.toContain(`\`### ${name}\``);
141	  });
142	
143	  test("both skills agree on the stored format version", () => {
144	    const written = linearPlan.match(/Format:\s*(v\d+)/)?.[1];
145	    expect(written).toBeTruthy();
146	    expect(linearRun).toContain(`\`${written}\``);
147	  });
148	
149	  test("the pipeline states no scoring threshold and no revision budget", () => {
150	    expect(pipeline).not.toContain("Scoring target");
151	    expect(pipeline).not.toMatch(/at most \w+ passes/);
152	    expect(pipeline).toContain("not a gate for any caller");
153	  });
154	
155	  test("linear:plan stores unconditionally, with no plan-mode transition", () => {
156	    expect(linearPlan).toContain("Storing is unconditional");
157	    expect(linearPlan).toContain("Do not add a separate approval step");
158	    expect(linearPlan).not.toContain("ExitPlanMode");
159	    expect(linearPlan).not.toContain("EnterPlanMode");
160	    expect(linearPlan).not.toContain("Decide whether to store");
161	  });
162	
163	  test("linear:run treats the stored plan as a durable artifact, not proof of approval", () => {
164	    expect(linearRun).toContain("checkable durable artifact");
165	    expect(linearRun).not.toContain("approval already happened when the plan was stored");
166	    expect(linearRun).not.toContain("plan somebody approved");
167	  });
168	
169	  test.each([
170	    ["revision", "Stored plan was drafted against"],
171	    ["path", "path(s) that no longer exist"],
172	  ])("linear:run reports %s drift", (_label, needle) => {
173	    expect(linearRun).toContain(needle);
174	  });
175	
176	  test("both drift reports stay advisory rather than becoming verdicts", () => {
177	    const [, drift = ""] = linearRun.split("report how far the plan has aged");
178	    expect(drift).toContain("advisory and never a verdict");
179	    // A drift report must not be smuggled in as a sixth plan-source verdict.
180	    for (const verdict of fallbackVerdicts) {
181	      expect(`drift section names ${verdict}: ${drift.includes(`**${verdict}**`)}`).toBe(
182	        `drift section names ${verdict}: false`,
183	      );
184	    }
185	  });
186	
187	  /**
188	   * Both carve-outs guard the same failure: the plan template stores an existing file as
189	   * `path/to/file.ts:NN` and a planned one with a `(new)` suffix, so a literal existence
190	   * test on the raw entry reports every file as missing — the cry-wolf outcome that would
191	   * make the report worthless.
192	   */
193	  test.each([
194	    ["files it intends to create", "absent by design"],
195	    ["a trailing line number", "Strip a trailing"],
196	  ])("the path check handles %s", (_label, needle) => {
197	    const [, drift = ""] = linearRun.split("**Path drift.**");
198	    expect(drift).toContain(needle);
199	  });
200	
201	  test("the pipeline gates the review step on plan alone", () => {
202	    expect(pipeline).toContain("the only caller that may skip");
203	    expect(pipeline).toContain("Score: skipped");
204	  });
205	
206	  test("plan's argument-hint carries the --experts-review flag", () => {
207	    expect(plan).toMatch(/argument-hint:.*--experts-review/);
208	  });
209	
210	  test.each([
211	    ["linear:plan", linearPlan],
212	    ["linear:run", linearRun],
213	    ["run", run],
214	    ["run-primed", runPrimed],
215	  ])("%s does not claim the --experts-review flag", (name, source) => {
216	    expect(`${name}: ${source.includes("--experts-review")}`).toBe(`${name}: false`);
217	  });
218	
219	  test("the unchanged callers state no threshold of their own", () => {
220	    for (const [name, source] of [
221	      ["plan", plan],
222	      ["run", run],
223	      ["run-primed", runPrimed],
224	    ] as const) {
225	      expect(`${name}: ${source.includes("Scoring target")}`).toBe(`${name}: false`);
226	    }
227	  });
228	
229	  test("ordinary plan and run know nothing of the stored plan", () => {
230	    for (const [name, source] of [
231	      ["plan", plan],
232	      ["run", run],
233	      ["run-primed", runPrimed],
234	    ] as const) {
235	      expect(`${name}: ${source.includes("## Implementation plan")}`).toBe(`${name}: false`);
236	    }
